private function getMenuLabel($pageId) { switch ($this->getData(['page', $pageId, 'typeMenu'])) { case '': return $this->getData(['page', $pageId, 'shortTitle']); case 'text': return $this->getData(['page', $pageId, 'shortTitle']); case 'icon': if ($this->getData(['page', $pageId, 'iconUrl']) != '') { return '<img alt="' . $this->getData(['page', $pageId, 'shortTitle']) . '" src="' . Helper::baseUrl(false) . self::FILE_DIR . 'source/' . $this->getData(['page', $pageId, 'iconUrl']) . '" />'; } else { return $this->getData(['page', $pageId, 'shortTitle']); } case 'icontitle': if ($this->getData(['page', $pageId, 'iconUrl']) != '') { return '<img alt="' . $this->getData(['page', $pageId, 'shortTitle']) . '" src="' . Helper::baseUrl(false) . self::FILE_DIR . 'source/' . $this->getData(['page', $pageId, 'iconUrl']) . '" data-tippy-content="' . $this->getData(['page', $pageId, 'shortTitle']) . '"/>'; } else { return $this->getData(['page', $pageId, 'shortTitle']); } case 'icontext': if ($this->getData(['page', $pageId, 'iconUrl']) != '') { return '<img alt="' . $this->getData(['page', $pageId, 'shortTitle']) . '" src="' . Helper::baseUrl(false) . self::FILE_DIR . 'source/' . $this->getData(['page', $pageId, 'iconUrl']) . '" />' . $this->getData(['page', $pageId, 'shortTitle']); } else { return $this->getData(['page', $pageId, 'shortTitle']); } default: return $this->getData(['page', $pageId, 'shortTitle']); } } public function showCookies() { if ($this->getData(['config', 'cookieConsent']) === false) { return; } if ($this->getInput('ZWII_COOKIE_CONSENT') === 'true') { return; } $item = '<div id="cookieConsent">'; $item .= '<div class="cookieClose">'; $item .= Template::ico('cancel'); $item .= '</div>'; $item .= '<h3>' . $this->getData(['locale', 'cookies', 'titleLabel']) . '</h3>'; $item .= '<p>' . $this->getData(['locale', 'cookies', 'mainLabel']) . '</p>'; if ( $this->getData(['locale', 'homePageId']) === $this->getUrl(0) ) { $item .= '<form method="POST" action="' . He