 'hideTitle']) === false or $this->getUrl(1) === 'config' ) ) { echo '<h1 id="sectionTitle">' . $this->core->output['title'] . '</h1>'; } echo $this->core->output['content']; } public function showFooter() { $positionFixed = ''; if ( $this->getData(['theme', 'footer', 'position']) === 'site' or ($this->getData(['theme', 'footer', 'position']) === 'hide' and $this->getUrl(0) === 'theme' ) ) { $position = 'site'; } else { $position = 'body'; if ($this->getData(['theme', 'footer', 'fixed']) === true) { $positionFixed = ' footerbodyFixed'; } echo '</div>'; } echo $this->getData(['theme', 'footer', 'position']) === 'hide' ? '<footer class="displayNone">' : '<footer>'; echo ($position === 'site') ? '<div class="container"><div class="row" id="footersite">' : '<div class="container-large' . $positionFixed . '"><div class="row" id="footerbody">'; switch ($this->getData(['theme', 'footer', 'template'])) { case '1': $class['left'] = "displayNone"; $class['center'] = "col12"; $class['right'] = "displayNone"; break; case '2': $class['left'] = "col6"; $class['center'] = "displayNone"; $class['right'] = "col6"; break; case '3': $class['left'] = "col4"; $class['center'] = "col4"; $class['right'] = "col4"; break; case '4': $class['left'] = "col12"; $class['center'] = "col12"; $class['right'] = "col12"; break; } echo '<div class="' . $class['left'] . '" id="footer' . $position . 'Left">'; if ($this->getData(['theme', 'footer', 'textPosition']) === 'left') { $this->showFooterText(); } if ($this->getData(['theme', 'footer', 'socialsPosition']) === 'left') { $this->showSocials(); } if ($this->getData(['theme', 'footer', 'copyrightPosition']) === 'left') { $this->showCopyright(); } echo '</div>'; echo '<div class="' . $class['center'] . '" id="footer' . $position . 'Center">'; if ($this->getData(['theme', 'footer', 'textPosition']) === 'center') { $this->showFooterText(); } if ($this->getData(['theme', 'footer', 'socialsPosition']) === 'center') { $this->showSocials(); } if ($this->getD