ldren = []; $allPages = $this->getData(['page']); if (is_array($allPages)) { $tempChildren = []; foreach ($allPages as $pageId => $pageData) { if (isset($pageData['parentPageId']) && $pageData['parentPageId'] === $childKey) { if ($pageData['role'] <= $this->getUser('role')) { $position = isset($pageData['position']) ? $pageData['position'] : 0; $tempChildren[$pageId] = $position; } } } asort($tempChildren); $grandChildren = array_keys($tempChildren); } $hasChildren = !empty($grandChildren) && $this->getData(['page', $childKey, 'hideMenuChildren']) === false && ($depth + 1 <= $maxDepth); $itemClass = 'navDepth' . $depth . ($hasChildren ? ' navParent' : ''); $items .= '<li id="' . $childKey . '" class="' . $itemClass . '">'; if ( ($this->getData(['page', $childKey, 'disable']) === true and $this->isConnected() === false) or ($this->getData(['page', $childKey, 'disable']) === true and $this->isConnected() === true and $this->getUser('role') < self::ROLE_EDITOR) ) { $pageUrl = ($this->getData(['locale', 'homePageId']) === $this->getUrl(0)) ? Helper::baseUrl(false) . $lParamHome : Helper::baseUrl() . $this->getUrl(0) . $lParam; $items .= '<a class="navLevel' . $depth . '" href="' . $pageUrl . '">'; } else { $pageUrl = ($this->getData(['locale', 'homePageId']) === $childKey) ? Helper::baseUrl(false) . $lParamHome : Helper::baseUrl() . $childKey . $lParam; $items .= '<a class="' . $active . 'navLevel' . $depth . ' ' . $parentId . '" href="' . $pageUrl . '"' . $targetBlank . '>'; } $items .= $this->getMenuLabel($childKey); if ($hasChildren) { $items .= Template::ico('down', ['margin' => 'left']); } $items .= '</a>'; if ($hasChildren) { $nextDepth = $depth + 1; $childrenHtml = $this->buildChildrenRecursive($grandChildren, $nextDepth, $maxDepth, $childKey, $currentPageId); if (!empty($childrenHtml)) { $cssClass = 'navSub navSubmenu' . $nextDepth; $items .= '<ul class="' . $cssClass . '">'; $items .= $childrenHtml; $items .= '</ul>'; } } $items .= '</li>'; } return $items; } p